import toml from 'toml';
import MarkdownIt from 'markdown-it';
import {createMarkdownRenderer} from 'vitepress';
const files = ['docs/dotfiles.md','docs/history.md','docs/bootstrap.md','docs/bootstrap/setup.md','docs/bootstrap/services.md'];
const renderer = await createMarkdownRenderer(path.resolve('docs'), {theme:'github-light'});
const markdown = new MarkdownIt();
let snippets=0, anchors=0, links=0;
const problems=[];
for(const file of files) {
 const current=fs.readFileSync(file,'utf8');
 const before=execFileSync('git',['show','origin/main:'+file],{encoding:'utf8'});
 const html=fs.readFileSync(file.replace('docs/','docs/.vitepress/dist/').replace(/\.md$/,'.html'),'utf8');
 for(const [,id] of renderer.render(before).matchAll(/<h[1-6]\b[^>]*\bid="([^"]+)"/g)) {
  anchors++;
  if(!html.includes(`id="${id}"`)) problems.push(`${file}: missing old anchor ${id}`);
 }
 for(const [,snippet] of current.matchAll(/```toml\n([\s\S]*?)```/g)) {
  try {toml.parse(snippet); snippets++;} catch(e){problems.push(`${file}: ${e.message}`);}
 }
 const tokens=markdown.parse(current.replace(/^---\n[\s\S]*?\n---\n/,''),{});
 for(const token of tokens.flatMap(t=>t.children??[])) {
  if(token.type!=='link_open')continue;
  const href=token.attrGet('href');
  if(!href || !(href.startsWith('/')||href.startsWith('#')))continue;
  const [page,fragment]=href.split('#');
  let dest=page?path.join('docs/.vitepress/dist',page):file.replace('docs/','docs/.vitepress/dist/').replace(/\.md$/,'.html');
  if(dest.endsWith('/'))dest+='index.html';
  else if(!path.extname(dest))dest+='.html';
  if(!fs.existsSync(dest)){problems.push(`${file}: missing linked page ${href}`);continue;}
  const linked=fs.readFileSync(dest,'utf8');
  if(fragment && !linked.includes(`id="${fragment}"`))problems.push(`${file}: missing linked anchor ${href}`);
  links++;
 }
}
if(problems.length){console.error(problems.join('\n'));process.exit(1);}
console.log(`Checked ${files.length} guides: ${snippets} TOML examples, ${anchors} original heading anchors, ${links} local links.`);
